const envelope = $json;
if (!envelope || envelope.type !== 'event.change_due' || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
const event = data.event ?? {};
const previous = data.previous ?? null;
const kind = data.change_kind;
if (!data.fan?.email || !event.slug || !event.title || !event.starts_at || !['updated','cancelled'].includes(kind)) throw new Error('Missing event change fields');
const base = ("https://virya.music" || 'https://virya.music').replace(/\/$/, '');
const polish = String(data.fan.locale || 'pl').toLowerCase().startsWith('pl');
const eventUrl = `${base}${polish ? '/pl' : ''}/live/${encodeURIComponent(event.slug)}/`;
const addTrigger = (value, trigger) => { try { const u = new URL(value); u.searchParams.set('trigger', trigger); return u.toString(); } catch { return null; } };
return [{ json: { event_id: envelope.id, mail: {
  template: 'crowdrelay-event-change',
  to: data.fan.email,
  variables: {
    display_name: data.fan.display_name ?? null,
    locale: data.fan.locale ?? 'pl-PL',
    change_kind: kind,
    event_title: event.title,
    starts_at: event.starts_at,
    venue: event.venue ?? null,
    venue_address: event.venue_address ?? null,
    city: event.city ?? null,
    previous_starts_at: previous?.starts_at ?? null,
    previous_venue: previous?.venue ?? null,
    previous_venue_address: previous?.venue_address ?? null,
    event_url: eventUrl,
    ticket_url: eventUrl + '#tickets',
    rsvp_url: addTrigger(event.bandsintown_event_url, 'rsvp_going'),
    follow_url: "https://www.bandsintown.com/a/15587796-virya" || 'https://www.bandsintown.com/a/15587796-virya?trigger=track'
  },
  idempotency_key: envelope.id
} } }];
